<?php
declare(strict_types=1);
use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Customers\CustomerService;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();$db=Connection::get();$b=(int)$u['business_id'];$q=trim((string)($_GET['q']??''));if(mb_strlen($q)<2){echo json_encode(['ok'=>true,'customers'=>[]]);exit;}$like='%'.$q.'%';$s=$db->prepare("SELECT c.id,c.name,c.phone,c.email,c.credit_enabled,c.credit_limit,c.credit_balance,c.price_level_id,pl.name price_level_name FROM customers c LEFT JOIN product_price_levels pl ON pl.id=c.price_level_id AND pl.business_id=c.business_id WHERE c.business_id=? AND (c.name LIKE ? OR c.phone LIKE ? OR c.email LIKE ? OR c.rfc LIKE ?) ORDER BY c.name LIMIT 20");$s->execute([$b,$like,$like,$like,$like]);$rows=$s->fetchAll();foreach($rows as &$c){$c['credit_available']=max(0,(float)$c['credit_limit']-(float)$c['credit_balance']);}echo json_encode(['ok'=>true,'customers'=>$rows],JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
